// # --- after_main: tasks runnable when the root returns still run once ---
// async def waiter(ev: Event) -> None:
//     try:
//         await ev.wait()                      # -> S_RESUME_0
//         print("after_main: waiter woke")
//     finally:
//         print("after_main: waiter finally")
::tpystd::tpy::Poll<::std::monostate> __coro_waiter::__poll__(::tpystd::coro::Waker waker) {
    try {
    while (true) switch (__state) {
    case S_RESUME_0: {  // after: await ev.wait()
        bool __fin_ran_1 = false;
        try {
            auto __r0 = ::tpy::poll_with_cancel(__sub_0, __cancel_pending, waker);
            if (__r0.is_pending()) return ::tpystd::tpy::Poll<::std::monostate>::pending();
            (void)std::move(__r0).value();
            __sub_0.reset();
            std::cout << "after_main: waiter woke" << "\n" << ::tpy::check_signals;
            __fin_ran_1 = true;
            this->__finally_0();
            __state = S_JOIN_0;
            continue;
        } catch (...) {
            __sub_0.reset();
            if (!__fin_ran_1) {
                this->__finally_0();
            }
            throw;
        }
    }
    case S_JOIN_0: {
        __state = S_DONE;
        return ::tpystd::tpy::Poll<::std::monostate>::ready(::std::monostate{});
    }
    case S_INITIAL:  // entry
        __state = S_DONE;  // until a yield sets where to resume
        [[fallthrough]];
    case S_JOIN_1: {
        try {
            __sub_0.emplace(ev);
            __state = S_RESUME_0;
            continue;
        } catch (...) {
            this->__finally_0();
            throw;
        }
    }
    case S_DONE: ::tpy::tpy_panic("poll after Ready");
    }
    } catch (...) {
        __state = S_DONE;
        throw;
    }
    __builtin_unreachable();
}

void __coro_waiter::__finally_0() {
    std::cout << "after_main: waiter finally" << "\n" << ::tpy::check_signals;
}

